handleEvent(event) {
  switch (event.type) {
    case "MsgLoaded":
      if (prefersDarkQuery.matches) {
        adaptMessageForDarkMode(getMessagePaneBrowser());
      }
      // Restore the scroll position of a message if it gets reloaded.
      if (messageScrolled) {
        getMessagePaneBrowser().contentDocument.documentElement.scrollTo({
          top: messageScrolled,
          behavior: "instant",
        });
        messageScrolled = 0;
      }
      break;

  );
  Assert.equal(
    aboutMessage.document.activeElement,
    aboutMessage.getMessagePaneBrowser(),
    "The focus should be on the message browser"
  );

  await assert_light_style();
});
